def counts(expected,predicted,positive):
    if len(expected)!=len(predicted): raise ValueError('length mismatch')
    pairs=list(zip(expected,predicted))
    return (sum(a==positive and b==positive for a,b in pairs),
            sum(a!=positive and b==positive for a,b in pairs),
            sum(a==positive and b!=positive for a,b in pairs))
assert counts([],[],'u')==(0,0,0)
print(counts(['u','n','u'],['u','u','n'],'u'))

import math
def log_probability(values):
    if any(p<0 or p>1 for p in values): raise ValueError('probability')
    return sum(math.log(p) if p else -math.inf for p in values)
assert log_probability([])==0
assert log_probability([0])==-math.inf
print(round(log_probability([0.5,0.25]),4))

def overlap(train,validation,test):
    a,b,c=map(set,(train,validation,test))
    return sorted((a&b)|(a&c)|(b&c))
assert overlap([],[],[])==[]
print(overlap(['a','b'],['c'],['b','d']))

def dense_relu(x,weights,biases):
    if len(weights)!=len(biases) or any(len(row)!=len(x) for row in weights):
        raise ValueError('shape mismatch')
    return [max(0,sum(a*b for a,b in zip(x,row))+bias) for row,bias in zip(weights,biases)]
assert dense_relu([0],[[1]],[-1])==[0]
print(dense_relu([2,-1],[[1,1],[-2,1]],[0,1]))

import math
def sigmoid(x):
    if x>=0:return 1/(1+math.exp(-x))
    z=math.exp(x)
    return z/(1+z)
assert sigmoid(-1000)==0
assert sigmoid(1000)==1
print(sigmoid(0))

